# Check girth
from collections import deque

def check_girth(edges, n):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check for triangles
    for u in range(n):
        neighbors = list(adj[u])
        for i in range(len(neighbors)):
            for j in range(i+1, len(neighbors)):
                if neighbors[j] in adj[neighbors[i]]:
                    return False

    # Check for 4-cycles
    for u in range(n):
        for v in range(u+1, n):
            if v in adj[u]:
                continue
            common = adj[u] & adj[v]
            if len(common) >= 2:
                return False

    return True

print("Girth >= 5:", check_girth(edges, 13))

# Check 5-colorable
def is_k_colorable(edges, n, k):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            valid = True
            for neighbor in adj[v]:
                if colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

print("5-colorable:", is_k_colorable(edges, 13, 5))

# Show a valid coloring
def get_coloring(edges, n, k):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            valid = True
            for neighbor in adj[v]:
                if colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    backtrack(0)
    return colors

print("Coloring:", get_coloring(edges, 13, 5))
